\begin{equation}
  \begin{aligned}
    \mathcal L_Z(q)&=\mathbb E_qS_\beta(\bm Z)+H(q),\\
    \operatorname{KL}(q\Vert p_\beta)
      &=\log Z_\beta-\mathcal L_Z(q).
  \end{aligned}
